const SOCIAL_DEFAULTS={linkedin:'https://www.linkedin.com/',instagram:'https://www.instagram.com/',facebook:'https://www.facebook.com/'};
function makeMembers(count, year='2026–27', prefix='Member'){
  const office=Math.min(6,count);const remaining=Math.max(0,count-office);const post=Math.min(6,Math.max(0,Math.round(remaining*.2)));const third=Math.ceil((remaining-post)/2);const second=remaining-post-third;
  const working=['Technical','Design','Events','PR & Content','Operations'];
  return Array.from({length:count},(_,i)=>{
    let domain,role='Member',academicGroup,programme;
    if(i<office){domain='Office bearers';role=officeRoles[i]||'Office Bearer';academicGroup='Office Bearer — Final Year';programme='B.Tech CSE';}
    else if(i<office+third){domain=working[(i-office)%working.length];academicGroup='Third Year';programme='B.Tech CSE';}
    else if(i<office+third+second){domain=working[(i-office-third)%working.length];academicGroup='Second Year';programme='B.Tech CSE';}
    else {domain=working[(i-office-third-second)%working.length];const k=i-(office+third+second);academicGroup=k%2===0?'M.Tech':'PhD';programme=academicGroup==='M.Tech'?'M.Tech CSE':'PhD CSE';}
    return {id:`${year.replace(/\D/g,'')}-${i+1}`,name:`${prefix} ${String(i+1).padStart(2,'0')}`,role,domain,academicGroup,programme,year,initials:String(i+1).padStart(2,'0'),photo:'',socials:{...SOCIAL_DEFAULTS}};
  });
}
