function inferredAcademicGroup(m,i,count){
  if(m.academicGroup)return m.academicGroup;
  if(m.domain==='Office bearers'||officeRoles.includes(m.role))return 'Office Bearer — Final Year';
  const nonOffice=Math.max(1,count-6);const relative=Math.max(0,i-6);
  if(relative<Math.ceil(nonOffice*.42))return 'Third Year';
  if(relative<Math.ceil(nonOffice*.84))return 'Second Year';
  return relative%2?'PhD':'M.Tech';
}
function normalizeMember(m,i,count,year){const academicGroup=inferredAcademicGroup(m,i,count);return {...m,year:m.year||year,academicGroup,programme:m.programme||(academicGroup.includes('Office Bearer')||academicGroup==='Third Year'||academicGroup==='Second Year'?'B.Tech CSE':academicGroup==='M.Tech'?'M.Tech CSE':'PhD CSE'),photo:m.photo||'',socials:{...SOCIAL_DEFAULTS,...(m.socials||{})}};}
function normalizeEvent(e){return {...e,poster:e.poster||'',registrationDeadline:e.registrationDeadline||'',eligibility:e.eligibility||'All CSE students',entry:e.entry||'Free',speakers:Array.isArray(e.speakers)?e.speakers:[],schedule:Array.isArray(e.schedule)?e.schedule:[],recap:e.recap||'',attendance:e.attendance||'',gallery:Array.isArray(e.gallery)?e.gallery:[],resources:Array.isArray(e.resources)?e.resources:[],form:Array.isArray(e.form)?e.form:[]};}
function mergeState(parsed={}){
  const base=structuredClone(defaultState);
  const events=(Array.isArray(parsed.events)?parsed.events:base.events).map(normalizeEvent);
  const rawMembers=Array.isArray(parsed.members)?parsed.members:base.members;
  const members=rawMembers.map((m,i)=>normalizeMember(m,i,rawMembers.length,'2026–27'));
  const rawCohorts=parsed.cohorts&&typeof parsed.cohorts==='object'?parsed.cohorts:base.cohorts;
  const cohorts=Object.fromEntries(Object.entries(rawCohorts).map(([year,list])=>[year,(Array.isArray(list)?list:[]).map((m,i,a)=>normalizeMember(m,i,a.length,year))]));
  return {
    ...base,...parsed,events,members,cohorts,
    projects:Array.isArray(parsed.projects)?parsed.projects:base.projects,
    resources:Array.isArray(parsed.resources)?parsed.resources:base.resources,
    achievements:Array.isArray(parsed.achievements)?parsed.achievements:base.achievements,
    responses:Array.isArray(parsed.responses)?parsed.responses:base.responses,
    announcements:Array.isArray(parsed.announcements)?parsed.announcements.map((x,i)=>typeof x==='string'?{id:`legacy-${i}`,text:x,pinned:false}:x):base.announcements,
    content:{...base.content,...(parsed.content||{})}
  };
}

function loadState(){try{return mergeState(JSON.parse(localStorage.getItem('cssEditorialFinal')||localStorage.getItem('cssEditorialV2')||'{}'))}catch{return structuredClone(defaultState)}}
let state=loadState();
function save(){localStorage.setItem('cssEditorialFinal',JSON.stringify(state));}
function reset(){localStorage.removeItem('cssEditorialFinal');localStorage.removeItem('cssEditorialV2');state=structuredClone(defaultState);route();toast('Prototype reset.');}
function esc(v=''){return String(v).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function eventBySlug(slug){return state.events.find(e=>e.slug===slug);}
function formatDate(date){return new Date(`${date}T12:00:00`).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});}
function md(date){const d=new Date(`${date}T12:00:00`);return {day:String(d.getDate()).padStart(2,'0'),month:d.toLocaleString('en',{month:'short'}).toUpperCase(),year:d.getFullYear()};}
function toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2200);}
function slugify(v){return String(v).trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
function announcementText(a){return typeof a==='string'?a:a.text;}
function uniqueId(prefix){return `${prefix}${Date.now()}${Math.random().toString(36).slice(2,6)}`;}

