function ticker(){const items=[...state.announcements].sort((a,b)=>Number(b.pinned)-Number(a.pinned));return `<div class="ticker" aria-label="Announcements"><div class="ticker-label">NOTICEBOARD</div><div class="ticker-track"><div>${[...items,...items].map((a,i)=>`<span>${a.pinned?'<b>PINNED</b> ':''}${esc(announcementText(a))} <b>${i%2?'↗':'•'}</b></span>`).join('')}</div></div></div>`;}
function eventPhase(e){if(e.status==='Ongoing')return 'Ongoing';if(e.status==='Past'||e.status==='Archived')return 'Past';return 'Upcoming';}
function posterColors(e){const map={Career:['#e84a27','#fffdf7','#12120f'],Placements:['#12120f','#f2efe6','#f2c14e'],Community:['#f2c14e','#12120f','#c76a4b'],Competition:['#6c5a8c','#fffdf7','#f2c14e'],Research:['#d2a233','#12120f','#fffdf7'],'Open source':['#c76a4b','#fffdf7','#12120f'],Technical:['#7b7368','#fffdf7','#f2c14e']};return map[e.category]||['#e84a27','#fffdf7','#12120f'];}
function eventPosterSrc(e){
  if(e.poster)return e.poster;
  const d=md(e.date),[bg,fg,accent]=posterColors(e);const words=String(e.title||'CSS EVENT').toUpperCase().split(/\s+/);const lines=[];for(let i=0;i<words.length;i+=2)lines.push(words.slice(i,i+2).join(' '));
  const title=lines.slice(0,3).map((line,i)=>`<text x="42" y="${330+i*76}" font-family="Arial,Helvetica,sans-serif" font-size="66" font-weight="900" fill="${fg}">${line.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</text>`).join('');
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="1000" viewBox="0 0 800 1000"><rect width="800" height="1000" fill="${bg}"/><rect x="28" y="28" width="744" height="944" fill="none" stroke="${fg}" stroke-width="4"/><text x="42" y="82" font-family="monospace" font-size="22" font-weight="700" fill="${fg}">CSS / NIT DURGAPUR</text><text x="42" y="136" font-family="monospace" font-size="18" font-weight="700" fill="${fg}">${String(e.category||'EVENT').toUpperCase()}</text><circle cx="690" cy="116" r="45" fill="${accent}"/><text x="42" y="250" font-family="Arial,Helvetica,sans-serif" font-size="130" font-weight="900" fill="${fg}">${d.day}</text><text x="250" y="240" font-family="monospace" font-size="32" font-weight="700" fill="${fg}">${d.month}<tspan x="250" dy="38">${d.year}</tspan></text>${title}<line x1="42" y1="790" x2="758" y2="790" stroke="${fg}" stroke-width="4"/><text x="42" y="838" font-family="monospace" font-size="22" font-weight="700" fill="${fg}">${String(e.time||'').toUpperCase()}</text><text x="42" y="884" font-family="monospace" font-size="22" font-weight="700" fill="${fg}">${String(e.venue||'CSE DEPARTMENT').toUpperCase().slice(0,34)}</text><text x="42" y="942" font-family="monospace" font-size="18" font-weight="700" fill="${fg}">${String(e.status||'EVENT').toUpperCase()}</text></svg>`;
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}
function poster(e,index=0,compact=false){const phase=eventPhase(e);return `<article class="poster-card ${compact?'compact':''} reveal" data-event-card data-search="${esc(`${e.title} ${e.category} ${e.status}`.toLowerCase())}" data-phase="${phase}" data-category="${esc(e.category)}"><a class="poster-card-media" href="#/events/${e.slug}"><img src="${esc(eventPosterSrc(e))}" alt="Poster for ${esc(e.title)}"></a><div class="poster-card-copy"><div class="poster-card-meta"><span>${formatDate(e.date)}</span><span>${esc(e.category)}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.deck||e.description)}</p><div class="poster-card-foot"><span class="event-state phase-${phase.toLowerCase()}">${esc(e.status)}</span><a href="#/events/${e.slug}">${phase==='Past'?'View recap':'View details'} ↗</a></div></div></article>`;}
function sectionTitle(index,kicker,title,copy=''){return `<div class="section-heading"><div class="section-index">${index}</div><div><p class="kicker">${kicker}</p><h2>${title}</h2>${copy?`<p class="section-intro">${copy}</p>`:''}</div></div>`;}
function emptyState(title,copy){return `<div class="empty-state"><strong>${esc(title)}</strong><p>${esc(copy)}</p></div>`;}

