function projectsPage(){
  const featured=state.projects[0];
  return `<div class="site-page">${nav('Projects')}${ticker()}<main id="main"><section class="page-intro wrap"><p class="edition">PROJECT DESK / 2026–27</p><div><h1>Build things the department keeps.</h1><p>Projects are documented as ongoing work—not decorative portfolio cards.</p></div></section><section class="project-lead wrap"><div><p class="kicker">CURRENT / ${esc(featured.status)}</p><h2>${esc(featured.title)}</h2><p>${esc(featured.description)}</p><dl><div><dt>Owner</dt><dd>${esc(featured.owner)}</dd></div><div><dt>Cycle</dt><dd>${esc(featured.year)}</dd></div><div><dt>Contributors</dt><dd>${featured.accepting?'Open':'Closed'}</dd></div></dl><a class="solid-link" href="#/team">Join a working group</a></div><div class="project-blueprint"><span>01 / WORKING FILE</span><strong>${esc(featured.title)}</strong><pre>STATUS  ${esc(featured.status.toUpperCase())}\nOWNER   ${esc(featured.owner.toUpperCase())}\nSTACK   ${featured.tags.map(t=>t.toUpperCase()).join(' / ')}\nNEXT    DOCUMENT · BUILD · REVIEW</pre></div></section><section class="project-index wrap"><div class="project-index-head"><span>No.</span><span>Project</span><span>Status</span><span>Owner</span><span>Contributors</span></div>${state.projects.map((p,i)=>`<article class="project-row reveal"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(p.title)}</strong><p>${esc(p.description)}</p><em>${p.tags.map(esc).join(' · ')}</em></div><b>${esc(p.status)}</b><span>${esc(p.owner)}</span><span class="${p.accepting?'open':'closed'}">${p.accepting?'Accepting':'Not open'}</span></article>`).join('')}</section><section class="project-principles wrap"><article><span>A</span><h3>Useful first.</h3><p>Internal tools and guides should solve a department problem before they try to impress anyone.</p></article><article><span>B</span><h3>Documented.</h3><p>Decisions, contributors, setup, and handover notes remain available to the next committee.</p></article><article><span>C</span><h3>Open to contribution.</h3><p>Projects clearly state where a new member can help and who currently owns the work.</p></article></section></main>${footer()}</div>`;
}
function resourcesPage(){
  const cats=['All',...new Set(state.resources.map(r=>r.category))];
  return `<div class="site-page">${nav('Resources')}${ticker()}<main id="main"><section class="page-intro wrap"><p class="edition">STUDENT DESK / LIVE INDEX</p><div><h1>Useful links should be findable twice.</h1><p>A practical index for opportunities, academics, placements, research, and department routines.</p></div></section><section class="resource-controls wrap"><div class="filter-group" id="resourceFilters">${cats.map((c,i)=>`<button class="filter-button ${i===0?'active':''}" data-resource-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><label class="event-search"><span>Search</span><input id="resourceSearch" placeholder="Guide, category, keyword"></label></section><section class="resource-library wrap">${state.resources.map((r,i)=>`<a class="resource-card reveal" href="${esc(r.url||'#')}" data-resource-card data-category="${esc(r.category)}" data-search="${esc(`${r.title} ${r.category} ${r.description}`.toLowerCase())}"><span>${String(i+1).padStart(2,'0')}</span><em>${esc(r.category)}</em><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><footer><b>${esc(r.meta)}</b><i>↗</i></footer></a>`).join('')}</section><section class="resource-callout wrap"><p class="kicker">MISSING SOMETHING?</p><h2>Suggest a guide, link, or opportunity.</h2><p>The admin panel can publish, categorise, update, and remove resources without changing the site code.</p><a class="solid-link" href="https://cssnitdgp.in" target="_blank" rel="noreferrer">Contact CSS</a></section></main>${footer()}</div>`;
}
function achievementsPage(){
  const years=[...new Set(state.achievements.map(a=>a.year))].sort((a,b)=>Number(b)-Number(a));
  return `<div class="site-page">${nav()}<main id="main"><section class="page-intro wrap"><p class="edition">DEPARTMENT RECORD / SINCE 2023</p><div><h1>Keep the record specific.</h1><p>Achievements, milestones, and support work belong in a public history—not only in social posts.</p></div></section><section class="record-summary wrap"><strong>${state.achievements.length}</strong><div><span>recorded items</span><p>Replace placeholders with verified event outcomes, student achievements, publications, competition results, and society milestones.</p></div></section><section class="timeline wrap">${years.map(year=>`<div class="timeline-year"><header><span>${year}</span><b>${state.achievements.filter(a=>a.year===year).length} entries</b></header><div>${state.achievements.filter(a=>a.year===year).map((a,i)=>`<article class="reveal"><span>${String(i+1).padStart(2,'0')}</span><div><em>${esc(a.type)}</em><h2>${esc(a.title)}</h2><p>${esc(a.detail)}</p></div></article>`).join('')}</div></div>`).join('')}</section></main>${footer()}</div>`;
}

function adminNav(active){
  const items=[['Dashboard','#/admin'],['Events','#/admin/events'],['Form builder','#/admin/form-builder'],['Responses','#/admin/responses'],['Projects','#/admin/projects'],['Resources','#/admin/resources'],['Achievements','#/admin/achievements'],['Team','#/admin/team'],['Content','#/admin/content']];
  return `<aside class="admin-side"><div class="admin-logo">CSS<br><span>ADMIN</span></div><nav>${items.map(([l,h])=>`<a class="${active===l?'active':''}" href="${h}">${l}</a>`).join('')}</nav><a href="#/home" class="admin-public">Public site ↗</a></aside>`;
}
function adminShell(active,title,sub,content,actions=''){return `<div class="admin-app">${adminNav(active)}<div class="admin-main"><header class="admin-top"><div><p>CSS / CONTENT DESK</p><h1>${title}</h1><span>${sub}</span></div><div>${actions}</div></header><main class="admin-content">${content}</main></div></div>`;}
function statusPill(v){return `<span class="admin-status">${esc(v)}</span>`;}
function adminDashboard(){
  const next=[...state.events].sort((a,b)=>a.date.localeCompare(b.date))[0];
  const content=`<div class="admin-stats six"><article><span>Events</span><strong>${state.events.length}</strong><em>${state.events.filter(e=>e.status==='Registration Open').length} collecting registrations</em></article><article><span>Responses</span><strong>${state.responses.length}</strong><em>across published events</em></article><article><span>Projects</span><strong>${state.projects.length}</strong><em>${state.projects.filter(p=>p.accepting).length} accepting contributors</em></article><article><span>Resources</span><strong>${state.resources.length}</strong><em>student desk entries</em></article><article><span>Current team</span><strong>${state.members.length}</strong><em>six working groups</em></article><article><span>Next event</span><strong>${next?md(next.date).day+' '+md(next.date).month:'—'}</strong><em>${next?esc(next.title):'No event published'}</em></article></div><div class="admin-columns"><section class="admin-panel"><div class="panel-head"><h2>Publishing queue</h2><a href="#/admin/events">Manage events</a></div>${state.events.slice(0,5).map(e=>`<div class="queue-row"><div><strong>${esc(e.title)}</strong><span>${formatDate(e.date)} · ${esc(e.venue)}</span></div>${statusPill(e.status)}</div>`).join('')}</section><section class="admin-panel"><div class="panel-head"><h2>Quick actions</h2></div><a class="admin-action" href="#/admin/events/new">Create an event <b>↗</b></a><a class="admin-action" href="#/admin/form-builder">Edit registration form <b>↗</b></a><a class="admin-action" href="#/admin/projects">Update projects <b>↗</b></a><a class="admin-action" href="#/admin/resources">Publish a resource <b>↗</b></a><a class="admin-action" href="#/admin/team">Update team roster <b>↗</b></a><a class="admin-action" href="#/admin/content">Edit noticeboard <b>↗</b></a></section></div>`;
  return adminShell('Dashboard','Dashboard','A practical control room for the society website.',content);
}
function adminEvents(){const rows=state.events.map(e=>`<tr data-event-row><td><strong>${esc(e.title)}</strong><small>${esc(e.category)}</small></td><td>${formatDate(e.date)}</td><td>${statusPill(e.status)}</td><td>${e.form.length}</td><td><a href="#/admin/events/edit/${e.slug}">Edit</a><a href="#/admin/form-builder?event=${e.slug}">Form</a><button type="button" data-delete-event="${e.slug}">Delete</button></td></tr>`).join('');return adminShell('Events','Events','Publish, edit, and archive events.',`<div class="admin-toolbar"><input id="adminEventSearch" placeholder="Search events"><a class="admin-primary" href="#/admin/events/new">New event</a></div><section class="admin-panel"><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Status</th><th>Fields</th><th>Actions</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No events</td></tr>'}</tbody></table></div></section>`);}
function eventEditorPage(slug){const isNew=slug==='new';const e=isNew?normalizeEvent({title:'',slug:'',date:'2026-09-30',time:'18:00',venue:'CSE Seminar Hall',category:'Workshop',status:'Draft',deck:'',description:'',poster:'',form:[]}):eventBySlug(slug);if(!e)return notFound();const speakerText=(e.speakers||[]).map(x=>[x.name,x.position,x.org,x.linkedin].filter(Boolean).join(' | ')).join('\n');const scheduleText=(e.schedule||[]).map(x=>`${x.time} | ${x.title}`).join('\n');const resourceText=(e.resources||[]).map(x=>`${x.label} | ${x.url}`).join('\n');const galleryText=(e.gallery||[]).join('\n');return adminShell('Events',isNew?'Create event':'Edit event','Every event keeps a poster, details, registration state, and archive material.',`<form id="eventEditor" data-original="${isNew?'':e.slug}" class="editor-layout"><section class="admin-panel editor-form"><label>Title<input name="title" required value="${esc(e.title)}"></label><div class="two"><label>Slug<input name="slug" required value="${esc(e.slug)}"></label><label>Status<select name="status">${['Draft','Upcoming','Registration Open','Save the Date','Ongoing','Closed','Past','Archived'].map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="two"><label>Date<input type="date" name="date" value="${e.date}"></label><label>Time<input type="time" name="time" value="${e.time}"></label></div><div class="two"><label>Venue<input name="venue" value="${esc(e.venue)}"></label><label>Category<input name="category" value="${esc(e.category)}"></label></div><label>Event poster image URL<input name="poster" value="${esc(e.poster||'')}" placeholder="https://… (generated poster is used until supplied)"></label><label>Or upload poster<input type="file" name="posterFile" accept="image/*"></label><label>Short deck<input name="deck" value="${esc(e.deck||'')}"></label><label>Full description<textarea name="description">${esc(e.description)}</textarea></label><div class="two"><label>Registration deadline<input type="datetime-local" name="registrationDeadline" value="${esc(e.registrationDeadline||'')}"></label><label>Eligibility<input name="eligibility" value="${esc(e.eligibility||'')}"></label></div><label>Entry / fee<input name="entry" value="${esc(e.entry||'Free')}"></label><label>Speakers — one per line: Name | Position | Organisation | LinkedIn<textarea name="speakers">${esc(speakerText)}</textarea></label><label>Schedule — one per line: Time | Item<textarea name="schedule">${esc(scheduleText)}</textarea></label><label>Past-event recap<textarea name="recap">${esc(e.recap||'')}</textarea></label><label>Attendance / result summary<input name="attendance" value="${esc(e.attendance||'')}"></label><label>Gallery image URLs — one per line<textarea name="gallery">${esc(galleryText)}</textarea></label><label>Resources — one per line: Label | URL<textarea name="resources">${esc(resourceText)}</textarea></label><label class="inline-check"><input type="checkbox" name="featured" ${e.featured?'checked':''}> Featured event</label><div class="editor-actions"><button class="admin-primary" type="submit">Save event</button><a href="#/admin/events">Cancel</a></div></section><aside class="editor-preview"><p>POSTER PREVIEW</p><div id="editorPoster">${poster(e,1,true)}</div><small>Every event always has a poster. Until real artwork is uploaded, a generated CSS poster is used automatically.</small></aside></form>`);}
function fieldBuilderItem(f,i){return `<article class="builder-field ${OPTION_TYPES.has(f.type)?'has-options':''}" data-field-id="${f.id}"><div><span>${String(i+1).padStart(2,'0')}</span><input data-field-label value="${esc(f.label)}"></div><select data-field-type>${Object.entries(FIELD_TYPES).map(([k,v])=>`<option value="${k}" ${k===f.type?'selected':''}>${v}</option>`).join('')}</select><label><input type="checkbox" data-field-required ${f.required?'checked':''} ${f.type==='section'?'disabled':''}> Required</label><div class="builder-actions"><button type="button" data-move="up" aria-label="Move up">↑</button><button type="button" data-move="down" aria-label="Move down">↓</button><button type="button" data-duplicate-field aria-label="Duplicate">⧉</button><button type="button" data-remove-field aria-label="Remove">×</button></div>${OPTION_TYPES.has(f.type)?`<label class="builder-options">Options, one per line<textarea data-field-options>${esc((f.options||[]).join('\n'))}</textarea></label>`:''}</article>`;}
function formBuilderPage(){const q=new URLSearchParams((location.hash.split('?')[1]||''));const e=eventBySlug(q.get('event'))||state.events[0];if(!e)return adminShell('Form builder','Registration form builder','Create an event before configuring its form.',emptyState('No event available','Create an event first.'));return adminShell('Form builder','Registration form builder','Add, reorder, require, and configure fields for each event.',`<div class="builder-top"><select id="builderEventSelect">${state.events.map(x=>`<option value="${x.slug}" ${x.slug===e.slug?'selected':''}>${esc(x.title)}</option>`).join('')}</select><button class="admin-primary" id="saveFormBuilder" type="button">Save form</button></div><div class="builder-layout"><aside class="admin-panel field-library"><h2>Field library</h2>${Object.entries(FIELD_TYPES).map(([k,v])=>`<button type="button" data-add-field="${k}">+ ${v}</button>`).join('')}</aside><section class="admin-panel"><h2>Form structure</h2><div id="fieldBuilderList" data-event="${e.slug}">${e.form.map(fieldBuilderItem).join('')||emptyState('No fields yet','Add a field from the library.')}</div></section><aside class="admin-panel live-form"><p>PUBLIC PREVIEW</p><h2>${esc(e.title)}</h2><div id="formLivePreview">${e.form.map(formField).join('')}</div></aside></div>`);}
function responseRows(filter='all'){const list=state.responses.filter(r=>filter==='all'||r.event===filter);return list.map(r=>`<tr data-response-id="${r.id}"><td>${esc(eventBySlug(r.event)?.title||r.event)}</td><td>${esc(r.name)}</td><td>${esc(r.email)}</td><td>${esc(r.submitted)}</td><td><button type="button" data-view-response="${r.id}">View</button><button type="button" data-delete-response="${r.id}">Delete</button></td></tr>`).join('')||'<tr><td colspan="5">No responses</td></tr>';}
function adminResponses(){return adminShell('Responses','Responses','Review registrations and export them.',`<div class="admin-toolbar"><select id="responseEventFilter"><option value="all">All events</option>${state.events.map(e=>`<option value="${e.slug}">${esc(e.title)}</option>`).join('')}</select><button id="exportCsv" type="button">Export CSV</button></div><section class="admin-panel"><div class="table-wrap"><table><thead><tr><th>Event</th><th>Name</th><th>Email</th><th>Submitted</th><th></th></tr></thead><tbody id="responseRows">${responseRows()}</tbody></table></div></section><dialog id="responseDialog" class="response-dialog"><button type="button" data-close-dialog>Close ×</button><div id="responseDialogBody"></div></dialog>`);}
function adminTeam(){const q=new URLSearchParams((location.hash.split('?')[1]||''));const year=q.get('year')||'2026–27';const list=year==='2026–27'?state.members:(state.cohorts[year]||[]);return adminShell('Team','Team roster','Manage academic group, programme, working group, photograph, and social links.',`<div class="admin-toolbar team-admin-toolbar"><select id="adminTeamYear">${['2026–27','2025–26','2024–25','2023–24'].map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select><input id="newMemberName" placeholder="Member name"><select id="newMemberAcademic"><option>Office Bearer — Final Year</option><option>Third Year</option><option>Second Year</option><option>M.Tech</option><option>PhD</option></select><select id="newMemberDomain">${departments.map(d=>`<option>${d[0]}</option>`).join('')}</select><input id="newMemberRole" placeholder="Role" value="Member"><input id="newMemberPhoto" placeholder="Photo URL"><input id="newMemberLinkedIn" placeholder="LinkedIn URL"><input id="newMemberInstagram" placeholder="Instagram URL"><input id="newMemberFacebook" placeholder="Facebook URL"><button class="admin-primary" id="addMember" type="button" data-year="${year}">Add member</button></div><section class="admin-panel"><div class="panel-head"><h2>${year} roster</h2><span>${list.length} members</span></div><div class="roster-admin roster-admin-rich">${list.map(m=>`<article><span>${esc(m.initials)}</span><div><strong>${esc(m.name)}</strong><em>${esc(m.role)} · ${esc(m.academicGroup)} · ${esc(m.domain)}</em></div><nav><a href="${esc(m.socials?.linkedin||'#')}" target="_blank">IN</a><a href="${esc(m.socials?.instagram||'#')}" target="_blank">IG</a><a href="${esc(m.socials?.facebook||'#')}" target="_blank">FB</a></nav><button type="button" data-remove-member="${m.id}" data-year="${year}">Remove</button></article>`).join('')||emptyState('No members','Add the first member for this cohort.')}</div></section>`);}
function adminContent(){return adminShell('Content','Homepage content','Edit the main headline, recruitment state, and noticeboard.',`<section class="admin-panel"><form id="contentSettings" class="content-form"><label>Hero headline<input name="heroTitle" value="${esc(state.content.heroTitle)}"></label><label class="inline-check"><input type="checkbox" name="joinOpen" ${state.content.joinOpen?'checked':''}> Recruitment is open</label><button class="admin-primary" type="submit">Save content</button><button id="resetPrototype" type="button">Reset prototype</button></form></section><section class="admin-panel notice-editor"><div class="panel-head"><h2>Noticeboard</h2><span>${state.announcements.length} items</span></div><div class="notice-add"><input id="newAnnouncement" placeholder="New announcement"><label><input type="checkbox" id="newAnnouncementPinned"> Pin</label><button class="admin-primary" id="addAnnouncement" type="button">Add</button></div>${state.announcements.map((a,i)=>`<div class="notice-row"><span>${String(i+1).padStart(2,'0')}</span><strong>${a.pinned?'<b>PINNED</b> ':''}${esc(announcementText(a))}</strong><button type="button" data-toggle-pin="${a.id}">${a.pinned?'Unpin':'Pin'}</button><button type="button" data-delete-announcement="${a.id}">Delete</button></div>`).join('')}</section>`);}
function adminProjects(){return adminShell('Projects','Projects','Maintain project status, ownership, and contributor availability.',`<form class="admin-toolbar multi" id="addProjectForm"><input name="title" placeholder="Project title" required><select name="status"><option>Proposed</option><option>Prototype</option><option>In progress</option><option>Maintained</option><option>Completed</option></select><input name="owner" placeholder="Owner" value="Technical Team"><label><input type="checkbox" name="accepting" checked> Accepting</label><button class="admin-primary" type="submit">Add project</button></form><section class="admin-panel"><div class="management-list">${state.projects.map((p,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(p.title)}</strong><em>${esc(p.status)} · ${esc(p.owner)}</em><p>${esc(p.description)}</p></div><button type="button" data-toggle-project="${p.id}">${p.accepting?'Close contributors':'Open contributors'}</button><button type="button" data-delete-project="${p.id}">Delete</button></article>`).join('')}</div></section>`);}
function adminResources(){return adminShell('Resources','Resources','Publish and remove student-desk entries.',`<form class="admin-toolbar multi" id="addResourceForm"><input name="title" placeholder="Resource title" required><input name="category" placeholder="Category" required><input name="meta" placeholder="Updated / count"><button class="admin-primary" type="submit">Add resource</button></form><section class="admin-panel"><div class="management-list">${state.resources.map((r,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(r.title)}</strong><em>${esc(r.category)} · ${esc(r.meta)}</em><p>${esc(r.description)}</p></div><button type="button" data-delete-resource="${r.id}">Delete</button></article>`).join('')}</div></section>`);}
function adminAchievements(){return adminShell('Achievements','Achievements','Maintain the public department record.',`<form class="admin-toolbar multi" id="addAchievementForm"><input name="title" placeholder="Achievement or milestone" required><input name="year" type="number" min="2023" max="2100" value="2026"><input name="type" placeholder="Type" value="Society milestone"><button class="admin-primary" type="submit">Add entry</button></form><section class="admin-panel"><div class="management-list">${state.achievements.map((a,i)=>`<article><span>${esc(a.year)}</span><div><strong>${esc(a.title)}</strong><em>${esc(a.type)}</em><p>${esc(a.detail)}</p></div><button type="button" data-delete-achievement="${a.id}">Delete</button></article>`).join('')}</div></section>`);}
function notFound(){return `<div class="site-page">${nav()}<main class="wrap not-found"><h1>404</h1><p>This page is not part of the prototype.</p><a class="solid-link" href="#/home">Return home</a></main>${footer()}</div>`;}

function route(){
  const raw=location.hash||'#/home';const [path]=raw.slice(2).split('?');const p=path.split('/').filter(Boolean);
  if(!p[0]||p[0]==='home')app.innerHTML=homePage();
  else if(p[0]==='events'&&p[1])app.innerHTML=eventDetailPage(p[1]);
  else if(p[0]==='events')app.innerHTML=eventsPage();
  else if(p[0]==='team')app.innerHTML=teamPage();
  else if(p[0]==='projects')app.innerHTML=projectsPage();
  else if(p[0]==='resources')app.innerHTML=resourcesPage();
  else if(p[0]==='achievements')app.innerHTML=achievementsPage();
  else if(p[0]==='admin'&&!p[1])app.innerHTML=adminDashboard();
  else if(p[0]==='admin'&&p[1]==='events'&&p[2]==='new')app.innerHTML=eventEditorPage('new');
  else if(p[0]==='admin'&&p[1]==='events'&&p[2]==='edit')app.innerHTML=eventEditorPage(p[3]);
  else if(p[0]==='admin'&&p[1]==='events')app.innerHTML=adminEvents();
  else if(p[0]==='admin'&&p[1]==='form-builder')app.innerHTML=formBuilderPage();
  else if(p[0]==='admin'&&p[1]==='responses')app.innerHTML=adminResponses();
  else if(p[0]==='admin'&&p[1]==='projects')app.innerHTML=adminProjects();
  else if(p[0]==='admin'&&p[1]==='resources')app.innerHTML=adminResources();
  else if(p[0]==='admin'&&p[1]==='achievements')app.innerHTML=adminAchievements();
  else if(p[0]==='admin'&&p[1]==='team')app.innerHTML=adminTeam();
  else if(p[0]==='admin'&&p[1]==='content')app.innerHTML=adminContent();
  else app.innerHTML=notFound();
  window.scrollTo(0,0);bind();
}

function bind(){
  const observer='IntersectionObserver'in window?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.08}):null;
  $$('.reveal').forEach(x=>observer?observer.observe(x):x.classList.add('visible'));
  const menu=$('#menuToggle'),mobile=$('#mobileNav');if(menu&&mobile)menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));mobile.classList.toggle('open',!open);document.body.classList.toggle('menu-open',!open);});
  $$('#mobileNav a').forEach(a=>a.addEventListener('click',()=>{mobile?.classList.remove('open');menu?.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open');}));

  const reg=$('#registrationForm');if(reg)reg.addEventListener('submit',e=>{e.preventDefault();const ev=eventBySlug(reg.dataset.slug);const data=new FormData(reg);const answers={};for(const [k,v] of data.entries()){const clean=k.replace(/\[\]$/,'');answers[clean]=answers[clean]?[].concat(answers[clean],v):v instanceof File?(v.name||'Uploaded file'):v;}const nameField=ev.form.find(f=>f.type==='text'&&/name/i.test(f.label))||ev.form.find(f=>f.type==='text');const emailField=ev.form.find(f=>f.type==='email');state.responses.push({id:uniqueId('r'),event:ev.slug,name:answers[nameField?.id]||'Registrant',email:answers[emailField?.id]||'',submitted:new Date().toLocaleString('en-IN'),answers});save();reg.innerHTML='<div class="form-success"><strong>Registration received.</strong><p>Your response is now visible in the admin prototype.</p></div>';toast('Registration submitted.');});

  const search=$('#eventSearch');const phaseButtons=$$('#eventPhaseFilters [data-event-phase]');const categoryButtons=$$('#eventCategoryFilters [data-event-category]');const applyEvents=()=>{const q=(search?.value||'').toLowerCase();const phase=$('#eventPhaseFilters .active')?.dataset.eventPhase||'All';const category=$('#eventCategoryFilters .active')?.dataset.eventCategory||'All';$$('[data-event-card]').forEach(card=>{const hit=card.dataset.search.includes(q)&&(phase==='All'||card.dataset.phase===phase)&&(category==='All'||card.dataset.category===category);card.hidden=!hit;});$$('[data-event-section]').forEach(sec=>{const visible=$$('[data-event-card]',sec).some(c=>!c.hidden);sec.hidden=!visible;});};if(search)search.addEventListener('input',applyEvents);phaseButtons.forEach(b=>b.addEventListener('click',()=>{phaseButtons.forEach(x=>x.classList.remove('active'));b.classList.add('active');applyEvents();}));categoryButtons.forEach(b=>b.addEventListener('click',()=>{categoryButtons.forEach(x=>x.classList.remove('active'));b.classList.add('active');applyEvents();}));
  const resourceSearch=$('#resourceSearch');const resourceButtons=$$('#resourceFilters [data-resource-category]');const applyResources=()=>{const q=(resourceSearch?.value||'').toLowerCase();const c=$('#resourceFilters .active')?.dataset.resourceCategory||'All';$$('[data-resource-card]').forEach(card=>card.hidden=!(card.dataset.search.includes(q)&&(c==='All'||card.dataset.category===c)));};if(resourceSearch)resourceSearch.addEventListener('input',applyResources);resourceButtons.forEach(b=>b.addEventListener('click',()=>{resourceButtons.forEach(x=>x.classList.remove('active'));b.classList.add('active');applyResources();}));
  

  const adminSearch=$('#adminEventSearch');if(adminSearch)adminSearch.addEventListener('input',()=>$$('[data-event-row]').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(adminSearch.value.toLowerCase())));
  $$('[data-delete-event]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Delete this event?')){state.events=state.events.filter(e=>e.slug!==b.dataset.deleteEvent);save();route();}}));
  const editor=$('#eventEditor');if(editor)editor.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(editor);const original=editor.dataset.original;const existing=original?eventBySlug(original):null;const slug=slugify(fd.get('slug'));if(!slug)return toast('Enter a valid slug.');if(state.events.some(x=>x.slug===slug&&x!==existing))return toast('That slug is already used.');let posterUrl=String(fd.get('poster')||'').trim()||existing?.poster||'';const posterFile=fd.get('posterFile');if(posterFile&&posterFile.size){posterUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(posterFile);});}const parseLines=(v)=>String(v||'').split(/\n/).map(x=>x.trim()).filter(Boolean);const speakers=parseLines(fd.get('speakers')).map(line=>{const [name='',position='',org='',linkedin='']=line.split('|').map(x=>x.trim());return{name,position,org,linkedin};});const schedule=parseLines(fd.get('schedule')).map(line=>{const [time='',title='']=line.split('|').map(x=>x.trim());return{time,title};});const resources=parseLines(fd.get('resources')).map(line=>{const [label='',url='']=line.split('|').map(x=>x.trim());return{label,url};});const obj=normalizeEvent({...(existing||{}),title:fd.get('title'),slug,status:fd.get('status'),date:fd.get('date'),time:fd.get('time'),venue:fd.get('venue'),category:fd.get('category'),poster:posterUrl,deck:fd.get('deck'),description:fd.get('description'),registrationDeadline:fd.get('registrationDeadline'),eligibility:fd.get('eligibility'),entry:fd.get('entry'),speakers,schedule,recap:fd.get('recap'),attendance:fd.get('attendance'),gallery:parseLines(fd.get('gallery')),resources,featured:fd.get('featured')==='on',form:existing?.form||[]});if(obj.featured)state.events.forEach(x=>x.featured=false);if(existing)state.events[state.events.indexOf(existing)]=obj;else state.events.push(obj);save();location.hash='#/admin/events';toast('Event saved.');});
  bindBuilder();

  const responseFilter=$('#responseEventFilter');if(responseFilter)responseFilter.addEventListener('change',()=>{$('#responseRows').innerHTML=responseRows(responseFilter.value);bindResponseActions();});
  const exportBtn=$('#exportCsv');if(exportBtn)exportBtn.addEventListener('click',exportCsv);bindResponseActions();

  const adminTeamYear=$('#adminTeamYear');if(adminTeamYear)adminTeamYear.addEventListener('change',()=>location.hash=`#/admin/team?year=${encodeURIComponent(adminTeamYear.value)}`);
  const add=$('#addMember');if(add)add.addEventListener('click',()=>{const name=$('#newMemberName').value.trim();if(!name)return toast('Enter a name.');const academicGroup=$('#newMemberAcademic').value;let domain=$('#newMemberDomain').value;let role=$('#newMemberRole').value.trim()||'Member';if(academicGroup==='Office Bearer — Final Year')domain='Office bearers';const programme=academicGroup.includes('Office Bearer')||academicGroup==='Third Year'||academicGroup==='Second Year'?'B.Tech CSE':academicGroup==='M.Tech'?'M.Tech CSE':'PhD CSE';const year=add.dataset.year;const member={id:uniqueId('m'),name,role,domain,academicGroup,programme,year,photo:$('#newMemberPhoto').value.trim(),socials:{linkedin:$('#newMemberLinkedIn').value.trim()||SOCIAL_DEFAULTS.linkedin,instagram:$('#newMemberInstagram').value.trim()||SOCIAL_DEFAULTS.instagram,facebook:$('#newMemberFacebook').value.trim()||SOCIAL_DEFAULTS.facebook},initials:name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()};if(year==='2026–27')state.members.push(member);else(state.cohorts[year]||(state.cohorts[year]=[])).push(member);save();route();});
  $$('[data-remove-member]').forEach(b=>b.addEventListener('click',()=>{const year=b.dataset.year;if(year==='2026–27')state.members=state.members.filter(m=>m.id!==b.dataset.removeMember);else state.cohorts[year]=(state.cohorts[year]||[]).filter(m=>m.id!==b.dataset.removeMember);save();route();}));

  const content=$('#contentSettings');if(content)content.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(content);state.content.heroTitle=fd.get('heroTitle');state.content.joinOpen=fd.get('joinOpen')==='on';save();toast('Content saved.');});
  const resetBtn=$('#resetPrototype');if(resetBtn)resetBtn.addEventListener('click',()=>{if(confirm('Reset all prototype data?'))reset();});
  const addNotice=$('#addAnnouncement');if(addNotice)addNotice.addEventListener('click',()=>{const text=$('#newAnnouncement').value.trim();if(!text)return toast('Enter an announcement.');state.announcements.push({id:uniqueId('n'),text,pinned:$('#newAnnouncementPinned').checked});save();route();});
  $$('[data-delete-announcement]').forEach(b=>b.addEventListener('click',()=>{state.announcements=state.announcements.filter(a=>a.id!==b.dataset.deleteAnnouncement);save();route();}));
  $$('[data-toggle-pin]').forEach(b=>b.addEventListener('click',()=>{const a=state.announcements.find(x=>x.id===b.dataset.togglePin);if(a){a.pinned=!a.pinned;save();route();}}));

  const projectForm=$('#addProjectForm');if(projectForm)projectForm.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(projectForm);state.projects.push({id:uniqueId('p'),title:fd.get('title'),status:fd.get('status'),owner:fd.get('owner'),year:'2026–27',description:'Add a project description from the production CMS.',tags:['New'],accepting:fd.get('accepting')==='on'});save();route();});
  $$('[data-delete-project]').forEach(b=>b.addEventListener('click',()=>{state.projects=state.projects.filter(p=>p.id!==b.dataset.deleteProject);save();route();}));
  $$('[data-toggle-project]').forEach(b=>b.addEventListener('click',()=>{const p=state.projects.find(x=>x.id===b.dataset.toggleProject);if(p){p.accepting=!p.accepting;save();route();}}));
  const resourceForm=$('#addResourceForm');if(resourceForm)resourceForm.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(resourceForm);state.resources.push({id:uniqueId('rs'),title:fd.get('title'),category:fd.get('category'),meta:fd.get('meta')||'New',description:'Add a concise description and verified external link from the production CMS.',url:'#'});save();route();});
  $$('[data-delete-resource]').forEach(b=>b.addEventListener('click',()=>{state.resources=state.resources.filter(r=>r.id!==b.dataset.deleteResource);save();route();}));
  const achievementForm=$('#addAchievementForm');if(achievementForm)achievementForm.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(achievementForm);state.achievements.unshift({id:uniqueId('a'),title:fd.get('title'),year:String(fd.get('year')),type:fd.get('type'),detail:'Add verified context, outcome, and related people from the production CMS.'});save();route();});
  $$('[data-delete-achievement]').forEach(b=>b.addEventListener('click',()=>{state.achievements=state.achievements.filter(a=>a.id!==b.dataset.deleteAchievement);save();route();}));
}
function bindResponseActions(){
  $$('[data-view-response]').forEach(b=>b.addEventListener('click',()=>{const r=state.responses.find(x=>x.id===b.dataset.viewResponse);const d=$('#responseDialog');if(!r||!d)return;$('#responseDialogBody').innerHTML=`<p class="kicker">${esc(eventBySlug(r.event)?.title||r.event)}</p><h2>${esc(r.name)}</h2><p>${esc(r.email)}</p><dl>${Object.entries(r.answers||{}).map(([k,v])=>`<div><dt>${esc(eventBySlug(r.event)?.form.find(f=>f.id===k)?.label||k)}</dt><dd>${esc(Array.isArray(v)?v.join(', '):v)}</dd></div>`).join('')}</dl>`;d.showModal();}));
  $$('[data-delete-response]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Delete this response?')){state.responses=state.responses.filter(r=>r.id!==b.dataset.deleteResponse);save();route();}}));
  $('[data-close-dialog]')?.addEventListener('click',()=>$('#responseDialog')?.close());
}
function bindBuilder(){
  const list=$('#fieldBuilderList');if(!list)return;const ev=eventBySlug(list.dataset.event);if(!ev)return;
  $$('[data-add-field]').forEach(b=>b.addEventListener('click',()=>{const type=b.dataset.addField;ev.form.push({id:uniqueId('f'),type,label:FIELD_TYPES[type],required:false,options:OPTION_TYPES.has(type)?['Option 1','Option 2']:undefined});save();route();}));
  $$('.builder-field').forEach(item=>{const field=ev.form.find(f=>f.id===item.dataset.fieldId);if(!field)return;
    $('[data-field-label]',item)?.addEventListener('input',e=>{field.label=e.target.value;refreshForm(ev);});
    $('[data-field-type]',item)?.addEventListener('change',e=>{field.type=e.target.value;if(OPTION_TYPES.has(field.type)&&!field.options)field.options=['Option 1','Option 2'];field.required=field.type==='section'?false:field.required;save();route();});
    $('[data-field-required]',item)?.addEventListener('change',e=>{field.required=e.target.checked;refreshForm(ev);});
    $('[data-field-options]',item)?.addEventListener('input',e=>{field.options=e.target.value.split('\n').map(x=>x.trim()).filter(Boolean);refreshForm(ev);});
    $('[data-remove-field]',item)?.addEventListener('click',()=>{ev.form=ev.form.filter(f=>f.id!==field.id);save();route();});
    $('[data-duplicate-field]',item)?.addEventListener('click',()=>{const i=ev.form.indexOf(field);ev.form.splice(i+1,0,{...structuredClone(field),id:uniqueId('f'),label:`${field.label} copy`});save();route();});
    $$('[data-move]',item).forEach(b=>b.addEventListener('click',()=>{const i=ev.form.indexOf(field);const j=b.dataset.move==='up'?i-1:i+1;if(j<0||j>=ev.form.length)return;[ev.form[i],ev.form[j]]=[ev.form[j],ev.form[i]];save();route();}));
  });
  $('#saveFormBuilder')?.addEventListener('click',()=>{save();toast('Form saved.');});
  $('#builderEventSelect')?.addEventListener('change',e=>location.hash=`#/admin/form-builder?event=${e.target.value}`);
}
function refreshForm(ev){const p=$('#formLivePreview');if(p)p.innerHTML=ev.form.map(formField).join('');}
function exportCsv(){const allKeys=[...new Set(state.responses.flatMap(r=>Object.keys(r.answers||{})))];const rows=[['Event','Name','Email','Submitted',...allKeys],...state.responses.map(r=>[eventBySlug(r.event)?.title||r.event,r.name,r.email,r.submitted,...allKeys.map(k=>Array.isArray(r.answers?.[k])?r.answers[k].join('; '):(r.answers?.[k]||''))])];const csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='css-responses.csv';a.click();URL.revokeObjectURL(a.href);}
window.addEventListener('hashchange',route);route();
